package com.securebiz.inventory.service;

import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;
import com.securebiz.audit.repository.ActivityLogRepository;import com.securebiz.inventory.api.StockOperationDtos.*;import com.securebiz.inventory.repository.InventoryRepository;import com.securebiz.inventory.repository.StockOperationRepository;import com.securebiz.shared.api.BusinessException;import com.securebiz.shared.api.PageResponse;import com.securebiz.shared.security.CurrentActor;
import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.util.*;

@Service
public class StockOperationService {
 private final StockOperationRepository operations;private final InventoryRepository inventory;private final ActivityLogRepository audit;private final ObjectMapper json;
 public StockOperationService(StockOperationRepository operations,InventoryRepository inventory,ActivityLogRepository audit,ObjectMapper json){this.operations=operations;this.inventory=inventory;this.audit=audit;this.json=json;}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional(readOnly=true)public PageResponse<TransferResponse> transfers(int page,int size){return PageResponse.of(operations.transfers(size,(long)page*size),page,size,operations.countTransfers());}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional public TransferResponse createTransfer(TransferRequest r){if(r.sourceWarehouseId().equals(r.destinationWarehouseId()))throw invalid("SAME_TRANSFER_WAREHOUSE","Source and destination must differ");Set<UUID> variants=new HashSet<>();for(var i:r.items())if(!variants.add(i.variantId()))throw invalid("DUPLICATE_TRANSFER_VARIANT","A variant may appear once");UUID id=UUID.randomUUID(),actor=CurrentActor.userId();try{var x=operations.createTransfer(id,"TRF-"+shortId(id),r,actor);audit.appendMutation(actor,"STOCK_TRANSFER_CREATE","inventory","stock_transfer",id,"null",write(x));return x;}catch(DataIntegrityViolationException e){throw invalid("INVALID_TRANSFER_REFERENCE","Warehouse or variant is invalid");}}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional public TransferResponse submitTransfer(UUID id){transitionTransfer(id,"DRAFT","PENDING_APPROVAL",false);return operations.transfer(id).orElseThrow();}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional public TransferResponse approveTransfer(UUID id){transitionTransfer(id,"PENDING_APPROVAL","APPROVED",true);return operations.transfer(id).orElseThrow();}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional public TransferResponse dispatch(UUID id){var t=lockTransfer(id,"APPROVED");UUID actor=CurrentActor.userId(),tx=UUID.randomUUID();var lines=operations.lockTransferLines(id);operations.createStockHeader(tx,"TRO-"+shortId(tx),t.source(),"TRANSFER_OUT",actor,"stock_transfer",id,"Transfer dispatch");for(var line:lines){inventory.ensureBalance(t.source(),line.variant());var b=inventory.lockBalance(t.source(),line.variant()).orElseThrow();BigDecimal after=b.quantity().subtract(line.requested());if(after.signum()<0)throw conflict("INSUFFICIENT_STOCK","Insufficient source stock for transfer");inventory.updateBalance(b.id(),after);operations.createStockItem(tx,line.variant(),line.requested().negate(),b.quantity(),after);operations.markDispatched(line.id(),line.requested());}if(operations.transitionTransfer(id,"APPROVED","DISPATCHED",actor)==0)throw conflict("TRANSFER_STATE_CONFLICT","Transfer state changed");audit.appendMutation(actor,"STOCK_TRANSFER_DISPATCH","inventory","stock_transfer",id,"{\"status\":\"APPROVED\"}","{\"status\":\"DISPATCHED\"}");return operations.transfer(id).orElseThrow();}
 @PreAuthorize("hasAuthority('inventory.transfer')")@Transactional public TransferResponse receive(UUID id){var t=lockTransfer(id,"DISPATCHED");UUID actor=CurrentActor.userId(),tx=UUID.randomUUID();var lines=operations.lockTransferLines(id);operations.createStockHeader(tx,"TRI-"+shortId(tx),t.destination(),"TRANSFER_IN",actor,"stock_transfer",id,"Transfer receipt");for(var line:lines){BigDecimal qty=line.dispatched();inventory.ensureBalance(t.destination(),line.variant());var b=inventory.lockBalance(t.destination(),line.variant()).orElseThrow();BigDecimal after=b.quantity().add(qty);inventory.updateBalance(b.id(),after);operations.createStockItem(tx,line.variant(),qty,b.quantity(),after);operations.markReceived(line.id(),qty);}if(operations.transitionTransfer(id,"DISPATCHED","COMPLETED",actor)==0)throw conflict("TRANSFER_STATE_CONFLICT","Transfer state changed");audit.appendMutation(actor,"STOCK_TRANSFER_RECEIVE","inventory","stock_transfer",id,"{\"status\":\"DISPATCHED\"}","{\"status\":\"COMPLETED\"}");return operations.transfer(id).orElseThrow();}
 private void transitionTransfer(UUID id,String from,String to,boolean approval){var t=lockTransfer(id,from);UUID actor=CurrentActor.userId();if(approval&&t.createdBy().equals(actor))throw conflict("SEGREGATION_OF_DUTIES","Transfer creator cannot approve it");if(operations.transitionTransfer(id,from,to,actor)==0)throw conflict("TRANSFER_STATE_CONFLICT","Transfer state changed");audit.appendMutation(actor,"STOCK_TRANSFER_"+to,"inventory","stock_transfer",id,"{\"status\":\""+from+"\"}","{\"status\":\""+to+"\"}");}
 private StockOperationRepository.TransferLock lockTransfer(UUID id,String status){var t=operations.lockTransfer(id).orElseThrow(()->notFound("TRANSFER_NOT_FOUND"));if(!t.status().equals(status))throw conflict("TRANSFER_STATE_CONFLICT","Transfer is not in "+status);return t;}
 @PreAuthorize("hasAuthority('inventory.stocktake')")@Transactional(readOnly=true)public PageResponse<StocktakeResponse> stocktakes(int page,int size){return PageResponse.of(operations.stocktakes(size,(long)page*size),page,size,operations.countStocktakes());}
 @PreAuthorize("hasAuthority('inventory.stocktake')")@Transactional public StocktakeResponse createStocktake(StocktakeRequest r){UUID id=UUID.randomUUID(),actor=CurrentActor.userId();try{var x=operations.createStocktake(id,"STK-"+shortId(id),r,actor);audit.appendMutation(actor,"STOCKTAKE_CREATE","inventory","stocktake",id,"null",write(x));return x;}catch(DataIntegrityViolationException e){throw invalid("INVALID_STOCKTAKE_WAREHOUSE","Warehouse is invalid");}}
 @PreAuthorize("hasAuthority('inventory.stocktake')")@Transactional public StocktakeResponse count(UUID id,CountRequest r){var s=operations.lockStocktake(id).orElseThrow(()->notFound("STOCKTAKE_NOT_FOUND"));if(!s.status().equals("COUNTING"))throw conflict("STOCKTAKE_STATE_CONFLICT","Stocktake is not counting");try{operations.saveCounts(id,r.items());}catch(IllegalArgumentException e){throw invalid("INVALID_STOCKTAKE_ITEM",e.getMessage());}return operations.stocktake(id).orElseThrow();}
 @PreAuthorize("hasAuthority('inventory.stocktake')")@Transactional public StocktakeResponse submitStocktake(UUID id){var s=operations.lockStocktake(id).orElseThrow(()->notFound("STOCKTAKE_NOT_FOUND"));if(!s.status().equals("COUNTING")||!operations.allCounted(id))throw conflict("STOCKTAKE_INCOMPLETE","All items must be counted");operations.transitionStocktake(id,"COUNTING","PENDING_APPROVAL",CurrentActor.userId());return operations.stocktake(id).orElseThrow();}
 @PreAuthorize("hasAuthority('inventory.stocktake')")@Transactional public StocktakeResponse approveStocktake(UUID id){var s=operations.lockStocktake(id).orElseThrow(()->notFound("STOCKTAKE_NOT_FOUND"));UUID actor=CurrentActor.userId();if(!s.status().equals("PENDING_APPROVAL"))throw conflict("STOCKTAKE_STATE_CONFLICT","Stocktake is not pending approval");if(s.createdBy().equals(actor))throw conflict("SEGREGATION_OF_DUTIES","Stocktake creator cannot approve it");var lines=operations.lockStocktakeLines(id);List<StockOperationRepository.StocktakeLine> changed=lines.stream().filter(x->x.variance()!=null&&x.variance().signum()!=0).toList();UUID tx=changed.isEmpty()?null:UUID.randomUUID();if(tx!=null)operations.createStockHeader(tx,"STA-"+shortId(tx),s.warehouse(),"STOCKTAKE",actor,"stocktake",id,"Approved stocktake variance");for(var line:changed){inventory.ensureBalance(s.warehouse(),line.variant());var b=inventory.lockBalance(s.warehouse(),line.variant()).orElseThrow();if(b.quantity().compareTo(line.system())!=0)throw conflict("STOCK_CHANGED_DURING_COUNT","Inventory changed after stocktake snapshot");BigDecimal after=line.actual();inventory.updateBalance(b.id(),after);operations.createStockItem(tx,line.variant(),line.variance(),b.quantity(),after);operations.linkAdjustment(line.id(),tx);}operations.transitionStocktake(id,"PENDING_APPROVAL","COMPLETED",actor);audit.appendMutation(actor,"STOCKTAKE_APPROVE","inventory","stocktake",id,"{\"status\":\"PENDING_APPROVAL\"}",write(operations.stocktake(id).orElseThrow()));return operations.stocktake(id).orElseThrow();}
 private String shortId(UUID id){return id.toString().substring(0,8).toUpperCase();}private String write(Object o){try{return json.writeValueAsString(o);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private BusinessException invalid(String c,String m){return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,c,m);}private BusinessException conflict(String c,String m){return new BusinessException(HttpStatus.CONFLICT,c,m);}private BusinessException notFound(String c){return new BusinessException(HttpStatus.NOT_FOUND,c,"Resource not found");}
}
